package app.dayflow;
import android.content.*;import android.net.Uri;import android.text.*;import android.view.*;import android.widget.*;import com.google.android.material.textfield.TextInputEditText;import org.json.*;
/** Lightweight plain/source note editor. Rich Markdown and formulas are an optional APK. */
public final class NoteEditor {
 private final MainActivity a;private JSONObject original;private final TextInputEditText title;private final EditText source;private final TextView status;private final FrameLayout area;private final TextView preview;private Uri external;private boolean writable,loading;private final NoteHistory history=new NoteHistory();private final android.os.Handler handler=new android.os.Handler(android.os.Looper.getMainLooper());private final Runnable remember=this::rememberDraft;
 private void rememberDraft(){if(a.noteState==this){history.capture(sourceText());keepDraft();}}
 public NoteEditor(MainActivity activity,JSONObject record){this(activity,record,true);}
 public NoteEditor(MainActivity activity,JSONObject record,boolean automatic){a=activity;history.attach(a.getCacheDir());original=record;LinearLayout page=a.editorPage("笔记",()->{if(save(false))a.home();});LinearLayout head=Ui.padded(a);page.addView(head);LinearLayout actions=Ui.row(a);head.addView(actions);actions.addView(Ui.button(a,"保存",true,()->save(true)),new LinearLayout.LayoutParams(0,-2,1));actions.addView(Ui.button(a,"导出",false,()->a.exportMarkdown(draft())),new LinearLayout.LayoutParams(0,-2,1));actions.addView(Ui.button(a,"↶",false,()->restore(false)),new LinearLayout.LayoutParams(Ui.dp(a,48),-2));actions.addView(Ui.button(a,"↷",false,()->restore(true)),new LinearLayout.LayoutParams(Ui.dp(a,48),-2));actions.addView(Ui.button(a,"Aa",false,this::font),new LinearLayout.LayoutParams(Ui.dp(a,48),-2));title=Ui.field(a,head,"笔记名称",record.optString("title"),false);title.setFilters(new InputFilter[]{new InputFilter.LengthFilter(1000)});LinearLayout modes=Ui.row(a);modes.addView(Ui.button(a,"编辑",false,()->showPreview(false)),new LinearLayout.LayoutParams(0,-2,1));modes.addView(Ui.button(a,"预览",false,()->showPreview(true)),new LinearLayout.LayoutParams(0,-2,1));head.addView(modes);head.addView(Ui.button(a,DocumentPlugins.available(a,DocumentPlugins.MD)?"完整 Markdown 编辑":"更多 Markdown 功能",false,()->{if(save(false))DocumentPlugins.edit(a,original);}));source=new EditText(a);source.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);source.setGravity(Gravity.TOP|Gravity.START);source.setTextColor(Ui.ink(a));source.setHintTextColor(Ui.muted(a));source.setHint("记录想法，支持直接编写Markdown源码…");source.setTextSize(a.prefs.getInt("note_font_size",17));source.setBackgroundColor(android.graphics.Color.TRANSPARENT);source.setPadding(Ui.dp(a,20),0,Ui.dp(a,20),Ui.dp(a,16));source.setText(record.optString("content"));source.setSaveEnabled(false);area=new FrameLayout(a);page.addView(area,new LinearLayout.LayoutParams(-1,0,1));area.addView(source,new FrameLayout.LayoutParams(-1,-1));ScrollView scroll=new ScrollView(a);scroll.setTag("preview");preview=Ui.text(a,"",a.prefs.getInt("note_font_size",17),false);preview.setTextIsSelectable(true);preview.setPadding(Ui.dp(a,20),Ui.dp(a,12),Ui.dp(a,20),Ui.dp(a,24));scroll.addView(preview);scroll.setVisibility(View.GONE);area.addView(scroll,new FrameLayout.LayoutParams(-1,-1));source.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(View v){}public void onViewDetachedFromWindow(View v){history.close();}});status=Ui.help(a,"基础笔记 · .md · 无固定字数上限");status.setPadding(Ui.dp(a,20),0,Ui.dp(a,20),0);page.addView(status);history.capture(sourceText());source.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){if(!loading){status.setText("未保存 · "+s.length()+" 字符");handler.removeCallbacks(remember);handler.postDelayed(remember,1600);}}public void afterTextChanged(Editable e){}});if(automatic&&DocumentPlugins.available(a,DocumentPlugins.MD)&&a.prefs.getBoolean("markdown_auto_open",true)&&!a.prefs.contains("plugin_document"))source.post(()->{if(a.noteState==this&&!a.isFinishing()&&!a.prefs.contains("plugin_document")&&save(false))DocumentPlugins.edit(a,original);});}
 private void showPreview(boolean on){source.setVisibility(on?View.GONE:View.VISIBLE);area.findViewWithTag("preview").setVisibility(on?View.VISIBLE:View.GONE);if(on){NoteTools.render(preview,sourceText());((android.view.inputmethod.InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(source.getWindowToken(),0);}else source.requestFocus();}
 private String sourceText(){return source.getText().toString();}private void restore(boolean redo){history.capture(sourceText());String value=redo?history.redo():history.undo();if(value==null){a.message("没有更多修改记录");return;}loading=true;source.setText(value);source.setSelection(source.length());loading=false;status.setText("未保存 · .md");}
 private void font(){LinearLayout page=a.fullPage("笔记字号",()->a.edit(draft()));SeekBar size=new SeekBar(a);size.setMax(20);size.setProgress(a.prefs.getInt("note_font_size",17)-12);TextView sample=Ui.text(a,"笔记字号",a.prefs.getInt("note_font_size",17),false);page.addView(sample);page.addView(size);size.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int n,boolean user){sample.setTextSize(12+n);a.prefs.edit().putInt("note_font_size",12+n).apply();}});page.addView(Ui.button(a,"返回笔记",true,()->a.edit(draft())));}
 public JSONObject draft(){try{return new JSONObject(original.toString()).put("title",title.getText().toString().trim()).put("content",sourceText()).put("content_format","markdown");}catch(JSONException e){throw new IllegalStateException(e);}}
 public void keepDraft(){if(a.noteState!=this)return;JSONObject value=draft();if(value.optString("content").equals(original.optString("content"))&&value.optString("title").equals(original.optString("title")))return;NoteDrafts.queue(a,value,message->a.runOnUiThread(()->{if(a.noteState==this)status.setText(message);}));}
 public void bindExternal(Uri uri,boolean write){external=uri;writable=write;status.setText(write?"保存会写回原文件":"本机笔记，可导出 .md");}public Uri externalUri(){return external;}public boolean externalWritable(){return writable;}public boolean persistForNavigation(){return save(false);}
 private boolean save(boolean feedback){try{JSONObject r=draft();Data db=Data.get(a);JSONObject current=db.find(r.getString("id"));if(current==null&&!feedback&&r.optString("content").isEmpty()&&r.optString("image_base64").isEmpty())return true;if(current!=null&&!current.optString("revision").equals(original.optString("revision")))throw new Exception("笔记已从其他设备更新，请先导出当前内容");if(r.optString("title").isEmpty()){r.put("title",java.time.LocalDate.now().toString());title.setText(r.optString("title"));}Data.validate(r);if(current==null||!r.optString("content").equals(current.optString("content"))||!r.optString("title").equals(current.optString("title"))){db.save(r);NoteTasks.fromNote(a,r);a.changed();}else r=current;original=r;NoteDrafts.clear(a,r.getString("id"));EditorSnapshot.clear(a,r.getString("id"));if(external!=null&&writable)try(java.io.Writer writer=new java.io.OutputStreamWriter(a.getContentResolver().openOutputStream(external,"wt"),java.nio.charset.StandardCharsets.UTF_8)){writer.write(MarkdownFiles.markdown(r));MarkdownDocuments.wrote(a,external,r);}status.setText("已保存 · .md");if(feedback)a.message("笔记已保存");return true;}catch(Exception e){a.message(e.getMessage());return false;}}
}
